// Copies the discovery-file reader from insomnium-mcp into src/, so this
// package compiles and publishes it without depending on insomnium-mcp.
// Runs before every build and type-check; the copy is not committed.

import { readFileSync, writeFileSync } from 'node:fs';

const source = new URL('../../insomnium-mcp/src/discovery.ts', import.meta.url);
const target = new URL('../src/discovery.ts', import.meta.url);

writeFileSync(
  target,
  '// GENERATED by scripts/sync-discovery.mjs: edit packages/insomnium-mcp/src/discovery.ts\n\n'
    + readFileSync(source, 'utf8'),
);
